BEGIN;
ALTER TABLE "SalesShipment" ADD COLUMN "tenant_id" UUID;
ALTER TABLE "SalesShipment" ADD COLUMN "customer_id" UUID;
ALTER TABLE "SalesShipmentDataset" ADD COLUMN "tenant_id" UUID;
ALTER TABLE "SalesShipmentDataset" ADD COLUMN "sales_contract_version_id" UUID;
ALTER TABLE "SalesShipmentDataset" ADD COLUMN "customer_id" UUID;
ALTER TABLE "SalesShipmentDataset" ADD COLUMN "load_country" CHAR(2);
ALTER TABLE "SalesShipmentDataset" ADD COLUMN "discharge_country" CHAR(2);
CREATE UNIQUE INDEX "SalesShipment_id_tenant_id_key" ON "SalesShipment"("id","tenant_id");
CREATE INDEX "SalesShipment_tenant_id_project_id_execution_state_idx" ON "SalesShipment"("tenant_id","project_id","execution_state");
CREATE UNIQUE INDEX "SalesShipmentDataset_id_tenant_id_key" ON "SalesShipmentDataset"("id","tenant_id");
CREATE UNIQUE INDEX "Project_sales_shipment_context_key" ON "Project"("id","primary_sales_contract_id","customer_master_id","tenant_id");
CREATE UNIQUE INDEX "SalesShipment_dataset_context_key" ON "SalesShipment"("id","sales_contract_id","customer_id","tenant_id");
ALTER TABLE "SalesShipment" ADD CONSTRAINT "SalesShipment_tenant_shape" CHECK (("tenant_id" IS NULL AND "customer_id" IS NULL) OR ("tenant_id" IS NOT NULL AND "customer_id" IS NOT NULL));
ALTER TABLE "SalesShipmentDataset" ADD CONSTRAINT "SalesShipmentDataset_tenant_shape" CHECK (("tenant_id" IS NULL AND "customer_id" IS NULL AND "sales_contract_version_id" IS NULL) OR ("tenant_id" IS NOT NULL AND "customer_id" IS NOT NULL AND "sales_contract_version_id" IS NOT NULL AND "load_country" IS NOT NULL AND "discharge_country" IS NOT NULL));
ALTER TABLE "SalesShipmentDataset" ADD CONSTRAINT "SalesShipmentDataset_schedule_valid" CHECK ("estimated_departure" IS NULL OR "estimated_arrival" IS NULL OR "estimated_arrival" >= "estimated_departure");
ALTER TABLE "SalesShipment" ADD CONSTRAINT "SalesShipment_tenant_fkey" FOREIGN KEY ("tenant_id") REFERENCES "Tenant"("id") ON DELETE NO ACTION ON UPDATE NO ACTION;
ALTER TABLE "SalesShipment" ADD CONSTRAINT "SalesShipment_project_tenant_fkey" FOREIGN KEY ("project_id","tenant_id") REFERENCES "Project"("id","tenant_id") ON DELETE NO ACTION ON UPDATE NO ACTION;
ALTER TABLE "SalesShipment" ADD CONSTRAINT "SalesShipment_contract_tenant_fkey" FOREIGN KEY ("sales_contract_id","tenant_id") REFERENCES "Contract"("id","tenant_id") ON DELETE NO ACTION ON UPDATE NO ACTION;
ALTER TABLE "SalesShipment" ADD CONSTRAINT "SalesShipment_project_context_fkey" FOREIGN KEY ("project_id","sales_contract_id","customer_id","tenant_id") REFERENCES "Project"("id","primary_sales_contract_id","customer_master_id","tenant_id") ON DELETE NO ACTION ON UPDATE NO ACTION;
ALTER TABLE "SalesShipment" ADD CONSTRAINT "SalesShipment_customer_tenant_fkey" FOREIGN KEY ("customer_id","tenant_id") REFERENCES "Customer"("id","tenant_id") ON DELETE NO ACTION ON UPDATE NO ACTION;
ALTER TABLE "SalesShipmentDataset" ADD CONSTRAINT "SalesShipmentDataset_tenant_fkey" FOREIGN KEY ("tenant_id") REFERENCES "Tenant"("id") ON DELETE NO ACTION ON UPDATE NO ACTION;
ALTER TABLE "SalesShipmentDataset" ADD CONSTRAINT "SalesShipmentDataset_shipment_tenant_fkey" FOREIGN KEY ("shipment_id","tenant_id") REFERENCES "SalesShipment"("id","tenant_id") ON DELETE NO ACTION ON UPDATE NO ACTION;
ALTER TABLE "SalesShipmentDataset" ADD CONSTRAINT "SalesShipmentDataset_header_context_fkey" FOREIGN KEY ("shipment_id","sales_contract_id","customer_id","tenant_id") REFERENCES "SalesShipment"("id","sales_contract_id","customer_id","tenant_id") ON DELETE NO ACTION ON UPDATE NO ACTION;
ALTER TABLE "SalesShipmentDataset" ADD CONSTRAINT "SalesShipmentDataset_contract_tenant_fkey" FOREIGN KEY ("sales_contract_id","tenant_id") REFERENCES "Contract"("id","tenant_id") ON DELETE NO ACTION ON UPDATE NO ACTION;
ALTER TABLE "SalesShipmentDataset" ADD CONSTRAINT "SalesShipmentDataset_contract_version_tenant_fkey" FOREIGN KEY ("sales_contract_version_id","sales_contract_id","tenant_id") REFERENCES "ContractVersion"("id","contract_id","tenant_id") ON DELETE NO ACTION ON UPDATE NO ACTION;
ALTER TABLE "SalesShipmentDataset" ADD CONSTRAINT "SalesShipmentDataset_customer_tenant_fkey" FOREIGN KEY ("customer_id","tenant_id") REFERENCES "Customer"("id","tenant_id") ON DELETE NO ACTION ON UPDATE NO ACTION;
ALTER TABLE "SalesShipmentDataset" ADD CONSTRAINT "SalesShipmentDataset_product_tenant_fkey" FOREIGN KEY ("coffee_specification_id","tenant_id") REFERENCES "CoffeeSpecification"("id","tenant_id") ON DELETE NO ACTION ON UPDATE NO ACTION;
ALTER TABLE "SalesShipment" DROP CONSTRAINT "fk_106_SalesShipment";
ALTER TABLE "SalesShipment" ADD CONSTRAINT "fk_106_SalesShipment" FOREIGN KEY ("active_dataset_id","id") REFERENCES "SalesShipmentDataset"("id","shipment_id") ON DELETE NO ACTION ON UPDATE NO ACTION DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "ProjectAuditEvent" DROP CONSTRAINT IF EXISTS "ProjectAuditEvent_action_allowed";
ALTER TABLE "ProjectAuditEvent" ADD CONSTRAINT "ProjectAuditEvent_action_allowed" CHECK ("action" IN ('PROJECT_CREATED','PROJECT_UPDATED','PROJECT_CANCELLED','PURCHASE_CONTRACT_CREATED','PROJECT_ACTIVATED','SUPPLIER_SHIPMENT_CREATED','SALES_SHIPMENT_CREATED'));
ALTER TABLE "IdempotencyRecord" DROP CONSTRAINT IF EXISTS "IdempotencyRecord_tenant_response_snapshot";
ALTER TABLE "IdempotencyRecord" ADD CONSTRAINT "IdempotencyRecord_tenant_response_snapshot" CHECK ("operation_id" NOT IN ('createPurchaseContract','createSupplierShipment','createSalesShipment') OR ("tenant_id" IS NOT NULL AND "response_body" IS NOT NULL));
COMMIT;
